// Get all neighbors of the current node from the graph
std::vector<Node*> neighbors = graph.get_neighbors(current_node);

// Calculate the tentative g value for each neighbor
double tentative_g = current_node->g + 1.0; // Assuming uniform edge cost of 1.0

for (Node* neighbor : neighbors) {
    // Skip if neighbor is already visited
    if (neighbor->visited) {
        continue;
    }

    // Calculate h value (heuristic) - Euclidean distance to end_node
    double dx = neighbor->x - end_node->x;
    double dy = neighbor->y - end_node->y;
    double h = std::sqrt(dx * dx + dy * dy);

    // If neighbor is not in open list or we found a better path
    if (neighbor->g > tentative_g) {
        neighbor->g = tentative_g;
        neighbor->h = h;
        neighbor->f = neighbor->g + neighbor->h;
        neighbor->parent = current_node;

        // Add to open list if not already present
        if (std::find(open_list.begin(), open_list.end(), neighbor) == open_list.end()) {
            open_list.push_back(neighbor);
        }
    }
}

// Sort open list by f value (for A* algorithm efficiency)
std::sort(open_list.begin(), open_list.end(), [](const Node* a, const Node* b) {
    return a->f < b->f;
});
// END_CODE

